#!/usr/bin/env python3
"""
Lisensi: GPL-3.0 (sama dengan proyek induk). Tanggal modifikasi: 2026-11-11.

Junkman / Marker mod untuk NFS Most Wanted Android (RanggaCasper/MostWanted-Android v1.4.0).

Skrip ini menerapkan beberapa patch 4-byte pada lib/arm64-v8a/libmain.so milik APK RESMI.
Skrip HANYA bekerja pada build yang isi instruksinya persis sama (tiap patch memverifikasi
kata aslinya dulu), jadi aman: kalau build berbeda, skrip berhenti tanpa mengubah apa pun.

Pemakaian:
    python apply_patch.py libmain.so libmain_patched.so --varian D

Varian:
    A  Pilihan marker 2 -> 6, marker tidak berkurang saat dipakai (Junkman tak habis).
    D  A + stok semua jenis dianggap tersedia + gerbang Backroom terbuka (semua kategori tampil).
    E  D + lewati cek data Junkman per mobil untuk 5 jenis dasar (EKSPERIMEN, bisa crash).
    F  D + garasi: batas beli mobil dinaikkan sampai total 25 (batas nyata save) dan hadiah pink slip
       saat garasi penuh tidak crash lagi (mobil tidak ditambahkan). Opsi --garasi N (bawaan 25).
    G  E + patch garasi F.
    H  F + baris menu CHEATS baru "IMMUNE TO SPIKES" (kebal paku ranjau polisi, bisa dinyalakan/dimatikan di menu).
"""
import argparse, hashlib, struct, sys

NOP = 0xD503201F

# (offset di libmain.so, kata asli, kata baru, grup, keterangan)
PATCHES = [
    (0x14AA69C, 0x7100051F, 0x7100151F, "M", "layar marker: batas pilih #1 (cmp #1 -> #5)"),
    (0x14AACB0, 0x7100093F, 0x7100193F, "M", "layar marker: batas pilih #2 (cmp #2 -> #6)"),
    (0x1480058, 0x5280004B, 0x528000CB, "M", "teks Selections Remaining #1: 2 -> 6"),
    (0x1480068, 0x5280004A, 0x528000CA, "M", "teks Selections Remaining (0 terpilih): 2 -> 6"),
    (0x1480248, 0x5280004B, 0x528000CB, "M", "teks Selections Remaining #2: 2 -> 6"),
    (0xE53F4C, 0xB82D483F, NOP, "R", "RemoveMarker: id marker tidak dihapus"),
    (0xE53F58, 0xB82A483F, NOP, "R", "RemoveMarker: flag marker tidak dihapus"),
    (0xE54784, 0x540001A1, NOP, "C", "CountMarkers: lewati cek id (record 1)"),
    (0xE547AC, 0x54000061, NOP, "C", "CountMarkers: lewati cek flag (record 1)"),
    (0xE547C4, 0x540001C1, NOP, "C", "CountMarkers: lewati cek id (record 2)"),
    (0xE547F0, 0x54000061, NOP, "C", "CountMarkers: lewati cek flag (record 2)"),
    (0xE5480C, 0x540001C1, NOP, "C", "CountMarkers: lewati cek id (record 3)"),
    (0xE54838, 0x54000061, NOP, "C", "CountMarkers: lewati cek flag (record 3)"),
    (0xE906A0, 0x54000141, NOP, "G", "gerbang Backroom: lewati cek id"),
    (0xE906B0, 0x540000C1, NOP, "G", "gerbang Backroom: lewati cek arg"),
    (0xE906C4, 0x540002E0, 0x14000017, "G", "gerbang Backroom: flag -> selalu ketemu"),
    (0x111F9C4, 0x54000761, 0x54001FA1, "S", "dukungan mobil: lewati cek data untuk 5 jenis dasar"),
    # K: garasi Safe House. Batas beli diukur dari TOTAL mobil di garasi (termasuk mobil pink slip),
    # dan pemberian mobil hadiah saat garasi penuh tidak lagi crash (mobil tidak ditambahkan).
    (0x14DC2B8, 0x7100291F, None, "K", "garasi Safe House: batas beli (cmp 10 -> --garasi, total mobil)"),
    (0xE70110, 0x5280084F, 0x5280004F, "K", "hitung mobil garasi: pink slip ikut dihitung (mask 0x42 -> 0x02)"),
    (0xEC5378, 0x7100651F, 0x7103211F, "K", "tambah mobil: cek batas 25 diganti penanganan gagal yang aman (cmp 25 -> 200)"),
    (0xEC54A4, 0x2900267F, 0x29002668, "K", "tambah mobil gagal (slot part habis): kembalikan record kosong, bukan null"),
    # H: menu CHEATS bawaan APK mendapat baris ke-8 "IMMUNE TO SPIKES" dan ke-9 "PS2 CONTROLS" (kebal paku ranjau polisi).
    # Fungsi PunctureTire (x86 0x1EDEE0) dicabangkan ke kode kecil di area mati ImGui::ShowMetricsWindow;
    # kode itu membaca byte Opt+0x39 (toggle menu). Kode cave ditulis lewat CAVE_* di bawah.
    (0x1192B64, 0x54000A08, 0x14206FEF, "H", "PunctureTire: cabang ke cave A (gerbang paku ranjau)"),
    (0x8E9B98, 0x7100A51F, 0x144313E8, "H", "menu Value: cmp -> cave B (id 44/45 = byte Opt+0x39/0x3a; id lain kembali ke tabel asli)"),
    (0x8ECCCC, 0xF101C39F, 0xF102439F, "H", "DrawUi: loop baris tab CHEATS 7 -> 9 (cmp x28,#0x70 -> #0x90)"),
    (0x8ECCD4, 0xD00099C8, 0x144307A5, "H", "DrawUi: tabel baris CHEATS -> cave D (salin 7 baris + IMMUNE TO SPIKES + PS2 CONTROLS)"),
    (0x8ED1C8, 0x90FFE402, 0xB0008602, "H", "menu MOD: teks 'Port by ...' -> cave (adrp)"),
    (0x8ED1CC, 0x913D1442, 0x91339042, "H", "menu MOD: teks 'Port by Rangga Casper | Modded by YBPUT' (add)"),
    (0x8DB3D0, 0x944B1834, 0x94434E05, "H", "XInputGetState: Poll() -> cave E (mode PS2 CONTROLS: remap tombol)"),
    (0x1004BB8, 0xA9BD7BFD, 0x1426A855, "L", "pencatat Heat: SetWorldHeat -> cave (menulis HEATLOG ke log)"),
    (0x9B7D8C, 0xA9BC7BFD, 0x143FDBF5, "L", "pencatat Heat: setter 0x16110 -> cave (menulis HEATLOG ke log)"),
    (0xA3DA6C, 0xB9400408, 0x143DC4D6, "L", "pencatat Heat: getter 0x336c0 -> cave (menulis HEATLOG ke log)"),
    (0x103D4E4, 0xA9BD7BFD, 0x1425C65A, "L", "pencatat Heat: MinHeatLevel -> cave (menulis HEATLOG ke log)"),
    (0xA043CC, 0xA9BD7BFD, 0x143EAAB6, "L", "pencatat Heat: fungsi 0x26ab0 -> cave (menulis HEATLOG ke log)"),
]
# Varian N = H + baris menu CUSTOM HEAT (OFF,1-6): menulis heat float N ke 24 slot mobil di tabel record mobil.
PATCHES += [(o, l, (0xF102839F if o == 0x8ECCCC else b), "N", k) for (o, l, b, g, k) in list(PATCHES) if g == "H"]
# Varian O = N + panah kiri (<) berfungsi, toggle MOD disimpan antar sesi (ybput_mod.bin), baris DUMP MEMORI (riset).
PATCHES += [(o, l, (0xF102C39F if o == 0x8ECCCC else b), "O", k) for (o, l, b, g, k) in list(PATCHES) if g == "H"]
# Varian P = O + heat pengejaran (pursuit) ditulis langsung: float heat perp (pola [heat][-1.0][0xAAAAAAAA]) diisi N.
PATCHES += [(o, l, (0xF102C39F if o == 0x8ECCCC else b), "P", k) for (o, l, b, g, k) in list(PATCHES) if g == "H"]
# Varian Q = P + tab SETTING (PS2 Controls & DUMP Memory dipindah ke sana). Tab: byte Opt+0x471 (0 CHEATS, 1 MY MUSIC, 2 SETTING).
PATCHES += [(o, l, (0x144309B9 if o == 0x8ECCCC else bb), "Q", k) for (o, l, bb, g, k) in list(PATCHES) if g == "H"]
PATCHES += [
    (0x8EC7CC, 0x3951C554, 0x14430AFD, "Q", "menu MOD: sorotan tab CHEATS -> cave (tab SETTING)"),
    (0x8EC8B4, 0x944AD5DF, 0x14430AC7, "Q", "menu MOD: tombol tab SETTING setelah MY MUSIC"),
]
# --- Varian Z (rilis final YBPUT): semua patch dalam satu grup (garasi 25 sudah tertanam) ---
PATCHES += [
    (0x8DB3D0, 0x944B1834, 0x94434E05, "Z", "final v1.4.0-YBPUT"),
    (0x8E9B98, 0x7100A51F, 0x144313E8, "Z", "final v1.4.0-YBPUT"),
    (0x8EC7CC, 0x3951C554, 0x14430AFD, "Z", "final v1.4.0-YBPUT"),
    (0x8EC8B4, 0x944AD5DF, 0x14430AC7, "Z", "final v1.4.0-YBPUT"),
    (0x8ECCCC, 0xF101C39F, 0x144309B9, "Z", "final v1.4.0-YBPUT"),
    (0x8ECCD4, 0xD00099C8, 0x144307A5, "Z", "final v1.4.0-YBPUT"),
    (0x8ED1C8, 0x90FFE402, 0xB0008602, "Z", "final v1.4.0-YBPUT"),
    (0x8ED1CC, 0x913D1442, 0x91339042, "Z", "final v1.4.0-YBPUT"),
    (0x8F112C, 0x944AC28D, 0x9442F8C7, "Z", "final v1.4.0-YBPUT"),
    (0x909878, 0x540001E0, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0x9504AC, 0x54000580, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0x9B7D8C, 0xA9BC7BFD, 0x143FE0E3, "Z", "final v1.4.0-YBPUT"),
    (0xA32B44, 0xB829482A, 0x143DF3E1, "Z", "final v1.4.0-YBPUT"),
    (0xA32B78, 0xB829482A, 0x143DF3E7, "Z", "final v1.4.0-YBPUT"),
    (0xE53F4C, 0xB82D483F, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE53F58, 0xB82A483F, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE54784, 0x540001A1, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE547AC, 0x54000061, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE547C4, 0x540001C1, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE547F0, 0x54000061, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE5480C, 0x540001C1, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE54838, 0x54000061, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE70110, 0x5280084F, 0x5280004F, "Z", "final v1.4.0-YBPUT"),
    (0xE906A0, 0x54000141, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE906B0, 0x540000C1, 0xD503201F, "Z", "final v1.4.0-YBPUT"),
    (0xE906C4, 0x540002E0, 0x14000017, "Z", "final v1.4.0-YBPUT"),
    (0xEC5378, 0x7100651F, 0x7103211F, "Z", "final v1.4.0-YBPUT"),
    (0xEC54A4, 0x2900267F, 0x29002668, "Z", "final v1.4.0-YBPUT"),
    (0x1192B64, 0x54000A08, 0x14206FEF, "Z", "final v1.4.0-YBPUT"),
    (0x1200EBC, 0xB829482A, 0x141EBADD, "Z", "final v1.4.0-YBPUT"),
    (0x1200EF0, 0xB829482A, 0x141EBAE3, "Z", "final v1.4.0-YBPUT"),
    (0x1353934, 0x9421D0AF, 0x9419708B, "Z", "final v1.4.0-YBPUT"),
    (0x1480058, 0x5280004B, 0x528000CB, "Z", "final v1.4.0-YBPUT"),
    (0x1480068, 0x5280004A, 0x528000CA, "Z", "final v1.4.0-YBPUT"),
    (0x1480248, 0x5280004B, 0x528000CB, "Z", "final v1.4.0-YBPUT"),
    (0x14AA69C, 0x7100051F, 0x7100151F, "Z", "final v1.4.0-YBPUT"),
    (0x14AACB0, 0x7100093F, 0x7100193F, "Z", "final v1.4.0-YBPUT"),
    (0x14DC2B8, 0x7100291F, 0x7100651F, "Z", "final v1.4.0-YBPUT"),
]
CAVE_Z_BYTES = bytes.fromhex("")
CAVE_Z_ORIG_SHA256 = "e0334edf8ce668cf10b3d0722770367cc9dc9fb6f85e7490459248c0a72232fd"
VARIAN = {"Z": "Z", "Q": "MRCGKQ", "P": "MRCGKP", "O": "MRCGKO", "N": "MRCGKN", "A": "MR", "D": "MRCG", "E": "MRCGS", "F": "MRCGK", "G": "MRCGSK", "H": "MRCGKH", "L": "MRCGKHL"}

# Kode cave (aarch64) untuk grup H. Menimpa awal fungsi mati ImGui::ShowMetricsWindow (tidak punya pemanggil).
CAVE_OFF = 0x19AEB20
CAVE_BYTES = bytes.fromhex("")
CAVE_L_BYTES = bytes.fromhex("")
CAVE_L_ORIG_SHA256 = "c74f35b5e627db88871f5558c4ebba03eaf213e031d8346c1d6835cb6e2a109e"
CAVE_N_BYTES = bytes.fromhex("")
CAVE_N_ORIG_SHA256 = "98ae90ddd0a35bd5b25413d2b3e27c0a9a3394981d4c71dae90bd5fd01ea37b9"
CAVE_O_BYTES = bytes.fromhex("")
CAVE_O_ORIG_SHA256 = "9fc475622fd6b24cdea9073fd37d3aed65f8b63bda517d37a48623e3b390132d"
CAVE_P_BYTES = bytes.fromhex("")
CAVE_P_ORIG_SHA256 = "23ff3197d5e76a26c451437a7d60f6e1ff6a96530ca27d86df386d9bb1eefee0"
CAVE_Q_BYTES = bytes.fromhex("")
CAVE_Q_ORIG_SHA256 = "b489e5b339fc7776d3e2cf853a87a904b7d84b4d8eeea21a1660bd9bd5baa2c3"
CAVE_ORIG_SHA256 = "385c0315dbaf35692d64d27b78d68f3cf40d11a20414163e6330b79432f33dac"


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("masuk", help="libmain.so asli dari APK resmi v1.4.0 (arm64-v8a)")
    ap.add_argument("keluar", help="nama file hasil patch")
    ap.add_argument("--varian", choices=sorted(VARIAN), default="D")
    ap.add_argument("--garasi", type=int, default=25, help="varian F/G: blokir pembelian mobil bila total mobil di garasi >= angka ini (1-25, bawaan 25)")
    a = ap.parse_args()

    data = bytearray(open(a.masuk, "rb").read())
    print("SHA-256 masukan:", hashlib.sha256(data).hexdigest())
    grup = VARIAN[a.varian]
    if not 1 <= a.garasi <= 25:
        sys.exit("--garasi harus 1-25 (batas nyata garasi = 25 mobil; tabel slot part di save hanya 25 entri)")
    terpakai = [(o, l, (0x7100011F | (a.garasi << 10)) if b is None else b, g, k) for (o, l, b, g, k) in PATCHES if g in grup]
    for off, lama, baru, g, ket in terpakai:
        if off + 4 > len(data) or struct.unpack_from("<I", data, off)[0] != lama:
            sys.exit(f"BERHENTI: isi 0x{off:x} tidak cocok ({ket}). Build ini berbeda; tidak ada yang diubah.")
    cave_b, cave_h = (CAVE_Z_BYTES, CAVE_Z_ORIG_SHA256) if "Z" in grup else (CAVE_L_BYTES, CAVE_L_ORIG_SHA256) if "L" in grup else (CAVE_Q_BYTES, CAVE_Q_ORIG_SHA256) if "Q" in grup else (CAVE_P_BYTES, CAVE_P_ORIG_SHA256) if "P" in grup else (CAVE_O_BYTES, CAVE_O_ORIG_SHA256) if "O" in grup else (CAVE_N_BYTES, CAVE_N_ORIG_SHA256) if "N" in grup else (CAVE_BYTES, CAVE_ORIG_SHA256)
    if "H" in grup or "N" in grup or "O" in grup or "P" in grup or "Q" in grup or "Z" in grup:
        asli = bytes(data[CAVE_OFF:CAVE_OFF + len(cave_b)])
        if hashlib.sha256(asli).hexdigest() != cave_h:
            sys.exit("BERHENTI: area cave tidak cocok dengan build v1.4.0. Tidak ada yang diubah.")
    for off, lama, baru, g, ket in terpakai:
        struct.pack_into("<I", data, off, baru)
        print(f"  [{g}] 0x{off:x}: {lama:08x} -> {baru:08x}  {ket}")
    if "H" in grup or "N" in grup or "O" in grup or "P" in grup or "Q" in grup or "Z" in grup:
        data[CAVE_OFF:CAVE_OFF + len(cave_b)] = cave_b
        print(f"  [H] 0x{CAVE_OFF:x}: {len(cave_b)} byte kode cave (area mati ImGui::ShowMetricsWindow)")
    open(a.keluar, "wb").write(data)
    print("Selesai. SHA-256 hasil:", hashlib.sha256(data).hexdigest())

if __name__ == "__main__":
    main()
